    @classmethod
    def domain_matches(cls, d: str) -> bool:
        return d in cls.DOMAINS

    @classmethod
    def from_symbol(cls, symbol: pybamm.Symbol) -> pybamm.Symbol:
        """Create z-average with simplifications."""
        if symbol.evaluates_on_edges("primary"):
            raise ValueError(
